import axios from 'axios';

const API_URL = "http://localhost:8085/v1/api/RapidAPI";

export const getAllMovies = () => axios.get(`${API_URL}/Disney/GetAll`);

export const changeMovieStatus = (id, status) =>
  axios.patch(`${API_URL}/Disney/Mongo/changeStatus/${id}?status=${status}`);

export const searchMoviesFromAPI = (name) =>
  axios.get(`${API_URL}/Disney/API/searchFull/${name}`);

export const createMovie = (movie) => {
  return axios.post(`${API_URL}/Disney/save`, movie);
};

export const updateMovie = (movie) =>
  axios.put(`${API_URL}/Disney/Mongo/update`, movie);
